local npcs={[261809]={["locations"]={"The Shaper's Terrace"},["name"]="Nanaya",["source"]="https://www.wowhead.com/forever/item=273128"},[263384]={["locations"]={"Riverglades"},["name"]="Mister Graphed",["source"]="https://www.wowhead.com/forever/item=249399/frilled-lichen"},[8983]={["locations"]={"Blackrock Depths"},["name"]="Golem Lord Argelmach",["source"]="https://www.wowhead.com/forever/item=273127"}}
local function clone(v)
 if type(v)~='table' then return v end
 local r={};for k,x in pairs(v) do r[k]=clone(x) end;return r
end
local function add(list,value)
 for _,v in ipairs(list) do if v==value then return end end;list[#list+1]=value
end
local function same(a,b)
 return a.kind==b.kind and a.id==b.id and a.name==b.name and a.method==b.method
end
local function merge(list,s)
 for _,old in ipairs(list) do if same(old,s) then
  old.zones=old.zones or {};for _,z in ipairs(s.zones) do add(old.zones,z) end
  old.materialChecked='2026-11-22';old.materialSource=s.url
  return
 end end
 list[#list+1]=clone(s)
end
P.MaterialSourceCoverage={checked='2026-11-22',items={}}
for id,record in pairs(npcs) do
 local n=P.NPCSources[id] or {id=id,name=record.name,points={},entrances={},locations={},source=record.source}
 P.NPCSources[id]=n;n.locations=n.locations or {}
 for _,z in ipairs(record.locations) do add(n.locations,z) end
end
for id,r in pairs(reviewed) do
 P.MaterialSourceCoverage.items[id]={count=#r.sources,url=r.url}
 local meta=P.ItemMeta[id] or {name=r.name,url=r.url,sources={}};P.ItemMeta[id]=meta
 meta.sources=meta.sources or {}
 for _,s in ipairs(r.sources) do
  -- Preserve the method distinction in metadata too: observations are not verified drops.
  local kind=s.method=='Vendor' and 'Vendor' or s.method=='Loot' and 'Drop' or s.method=='Report' and 'Report' or s.method=='Disench.' and 'Disenchant' or 'Gather'
  local m={kind=kind,id=s.id,name=s.name,method=s.method,zones=clone(s.zones),zone=table.concat(s.zones,', '),url=s.url,source=s.provenance}
  if s.kind=='npc' then m.npc=s.id end;merge(meta.sources,m)
 end
end
for _,entries in pairs(P.GatherAtlas) do for _,e in ipairs(entries) do
 local r=reviewed[e.item]
 if r then
  e.sources=e.sources or {};e.referenceURLs=e.referenceURLs or {}
  if r.supersedePlayerReports then
   e.historicalSourceReports=e.historicalSourceReports or {}
   for i=#e.sources,1,-1 do local s=e.sources[i]
    if s.kind=='report' and (s.url or ''):find('reddit.com/',1,true) then
     e.historicalSourceReports[#e.historicalSourceReports+1]=table.remove(e.sources,i)
    end
   end
  end
  for _,s in ipairs(r.sources) do merge(e.sources,s);add(e.referenceURLs,s.url) end
  for _,url in ipairs(r.references or {}) do add(e.referenceURLs,url) end
  add(e.referenceURLs,r.url)
  if r.note then e.note=r.note
  elseif r.appendNote and not (e.note or ''):find(r.appendNote,1,true) then e.note=(e.note and e.note..' ' or '')..r.appendNote end
  if e.sourceCoverage and e.sourceCoverage.unavailable then e.sourceCoverage=nil end
  e.dropResearch=nil;e.materialSourceChecked='2026-11-22'
  e.sub=(e.sub or 'Material'):gsub(' | %d+ sources','')..' | '..#e.sources..' sources'
  local search=e.searchText or ''
  for _,s in ipairs(r.sources) do
   local text=(s.name..' '..table.concat(s.zones,' ')):lower()
   if not search:lower():find(text,1,true) then search=search..' '..text end
  end
  e.searchText=search:lower()
 end
end end
